//! Contract fixtures — the frozen wire bytes of `tests/fixtures/bridge/`.
//!
//! Written by the `contract` shard (wave 0) and READ-ONLY afterwards. The
//! two lanes do not edit this file to fit their implementation; they make
//! the implementation reproduce these bytes.
//!
//! Two oracles, exactly as the contract pins them:
//!
//! * **Requests are byte-exact.** Parsing a request fixture and re-encoding
//!   it through the production codec must return the fixture's bytes.
//! * **Responses are schema-equal after a documented volatile-field mask.**
//!   `uptime_ms`, `handling_ms`, `engine_version` and `db.path` are volatile
//!   by nature (wall clock, machine, package version), so they are masked
//!   before comparison. Everything else must match exactly.

use std::path::PathBuf;

use mem_bridge::engine::{Engine, EngineConfig};
use mem_bridge::jsonrpc::{
    Request, RequestId, Response, encode_request, encode_response, parse_line,
};
use serde_json::{Value, json};

// ---------------------------------------------------------------------------
// Fixture helpers
// ---------------------------------------------------------------------------

fn fixture_dir() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../tests/fixtures/bridge")
}

fn fixture(name: &str) -> String {
    let path = fixture_dir().join(name);
    std::fs::read_to_string(&path)
        .unwrap_or_else(|error| panic!("fixture {} is unreadable: {error}", path.display()))
}

fn full_engine() -> Engine {
    Engine::new(EngineConfig::default())
}

fn request(name: &str) -> Request {
    parse_line(&fixture(name)).unwrap_or_else(|error| panic!("{name} must parse: {error:?}"))
}

/// The documented volatile-field mask (bridge-schema.md §1, contract gate M37).
/// Field paths may be nested (`result.uptime_ms` inside the result object), so
/// a volatile name matches the full path OR its `.<name>` suffix path — the
/// rework (coder-inline): the original top-level-only match let
/// `result.uptime_ms` flakily through.
const VOLATILE: [&str; 4] = ["uptime_ms", "handling_ms", "engine_version", "db.path"];

fn vola(path: &str) -> bool {
    VOLATILE.contains(&path)
        || VOLATILE
            .iter()
            .filter(|name| **name != "db.path")
            .any(|name| path.ends_with(&format!(".{name}")))
}

fn mask(value: &Value, path: &str) -> Value {
    match value {
        Value::Object(map) => {
            let mut masked = serde_json::Map::new();
            for (key, child) in map {
                let child_path = if path.is_empty() {
                    key.clone()
                } else {
                    format!("{path}.{key}")
                };
                if vola(&child_path) {
                    masked.insert(key.clone(), json!("<masked>"));
                } else {
                    masked.insert(key.clone(), mask(child, &child_path));
                }
            }
            Value::Object(masked)
        }
        Value::Array(items) => Value::Array(items.iter().map(|item| mask(item, path)).collect()),
        other => other.clone(),
    }
}

fn assert_response_schema_equal_after_mask(
    engine: &Engine,
    fixture_name: &str,
    request_name: &str,
) {
    let response = engine.dispatch(&request(request_name));
    let actual = serde_json::to_value(&response).expect("response serializes");
    let expected: Value = serde_json::from_str(&fixture(fixture_name))
        .unwrap_or_else(|error| panic!("{fixture_name} must parse: {error}"));
    assert_eq!(
        mask(&actual, ""),
        mask(&expected, ""),
        "{fixture_name}: response drifted from the frozen schema"
    );
}

// ---------------------------------------------------------------------------
// Requests: byte-exact
// ---------------------------------------------------------------------------

#[test]
fn test_hello_request_fixture_byte_equal() {
    let bytes = fixture("hello-request.json");
    let request = parse_line(&bytes).expect("hello request parses");
    assert_eq!(request.method, "hello");
    assert_eq!(request.id.as_str(), Some("hello-1"));
    assert_eq!(encode_request(&request), bytes);
}

#[test]
fn test_capture_request_fixture_byte_equal() {
    let bytes = fixture("capture-request.json");
    let request = parse_line(&bytes).expect("capture request parses");
    assert_eq!(request.method, "capture");
    assert_eq!(request.id.as_str(), Some("capture-1"));
    assert_eq!(
        request.params.get("capture_id").and_then(Value::as_str),
        Some("019a2b3c-4d5e-7f00-8a9b-0c1d2e3f4a5b")
    );
    assert_eq!(encode_request(&request), bytes);
}

