/// The parse-error sample is an error **envelope**, not a request: the JS lane
/// emits no responses, so the byte-equality oracle here is the frozen envelope
/// reproduced through the production codec (bridge-schema.md §4).
#[test]
fn test_error_parse_request_fixture_byte_equal() {
    let bytes = fixture("error-32700.json");
    let response: Response = serde_json::from_str(&bytes)
        .unwrap_or_else(|error| panic!("error-32700.json must parse: {error}"));
    let error = response.error.as_ref().expect("envelope carries an error");
    assert_eq!(error.code, -32700);
    assert_eq!(response.id, RequestId::Null);
    assert_eq!(encode_response(&response), bytes);
}

#[test]
fn test_ndjson_framing_request_fixture_byte_equal() {
    let bytes = fixture("ndjson-framing.txt");
    let mut encoded = String::new();
    for line in bytes.lines() {
        let request = parse_line(line).expect("every framing line parses");
        encoded.push_str(&encode_request(&request));
    }
    assert_eq!(bytes.lines().count(), 3, "hello, capture, health");
    assert_eq!(encoded, bytes, "NDJSON framing drifted");
}

