// ---------------------------------------------------------------------------
// Error envelopes: byte-exact (the engine's canonical error form)
// ---------------------------------------------------------------------------

#[test]
fn test_error_32700_fixture_byte_equal() {
    let bytes = fixture("error-32700.json");
    assert_eq!(encode_response(&Response::parse_error()), bytes);
}

#[test]
fn test_error_32600_fixture_byte_equal() {
    let bytes = fixture("error-32600.json");
    assert_eq!(encode_response(&Response::invalid_request()), bytes);
}

#[test]
fn test_error_32601_fixture_byte_equal() {
    let bytes = fixture("error-32601.json");
    assert_eq!(
        encode_response(&Response::error(
            RequestId::String("unknown-1".to_owned()),
            mem_bridge::error_map::code_for(mem_bridge::error_map::ErrorKind::UnknownMethod),
            mem_bridge::error_map::message_for(mem_bridge::error_map::ErrorKind::UnknownMethod),
        )),
        bytes
    );
}

#[test]
fn test_error_32602_fixture_byte_equal() {
    let bytes = fixture("error-32602.json");
    let expected: Value = serde_json::from_str(&bytes).expect("envelope parses");
    let data = expected["error"]["data"].clone();
    let session_id = data["session_id"]
        .as_str()
        .expect("the -32602 fixture carries the offending session_id");
    assert!(
        session_id.chars().count() > 128,
        "the -32602 fixture must carry a value over the 128-char bound (M6)"
    );
    let id = expected["id"].as_str().expect("string id").to_owned();
    assert_eq!(
        encode_response(&Response::error_with_data(
            RequestId::String(id),
            mem_bridge::error_map::code_for(mem_bridge::error_map::ErrorKind::OverlongSessionId),
            mem_bridge::error_map::message_for(mem_bridge::error_map::ErrorKind::OverlongSessionId),
            data,
        )),
        bytes
    );
}

